fixed_template.netlist_template:
* Parameterized unity-gain Sallen-Key low-pass
.param RValue=$r FcValue=$fc CValue={1/(6.283185307179586*RValue*FcValue)}
Vin vin 0 DC 0 AC 1
R1 vin n1 {RValue}
R2 n1 n2 {RValue}
C1 n1 vout {CValue}
C2 n2 0 {CValue}
Xop n2 vout vout ideal_opamp
Rload vout 0 100k
.subckt ideal_opamp inp inn out
Eout out 0 inp inn 1e6
.ends ideal_opamp
.op
.end
